# ----- lib/i18n.sh -----

deploy_lang="${DEPLOY_LANG:-${LANGUAGE:-${LC_ALL:-${LC_MESSAGES:-${LANG:-en}}}}}"
deploy_lang="${deploy_lang%%.*}"
deploy_lang="${deploy_lang%%_*}"

case "${deploy_lang,,}" in
  zh|cn) DEPLOY_LANG="zh" ;;
  *) DEPLOY_LANG="en" ;;
esac

declare -gA __DEPLOY_I18N_EN=()
declare -gA __DEPLOY_I18N_ZH=()

i18n_register() {
  local key="$1"
  local en="$2"
  local zh="${3:-$2}"
  __DEPLOY_I18N_EN["$key"]="$en"
  __DEPLOY_I18N_ZH["$key"]="$zh"
}

i18n_register_many() {
  while [[ $# -gt 0 ]]; do
    if [[ $# -lt 3 ]]; then
      printf 'i18n_register_many requires key/en/zh triples\n' >&2
      return 1
    fi
    i18n_register "$1" "$2" "$3"
    shift 3
  done
}

i18n_print() {
  local text="$1"
  shift || true
  if [[ $# -gt 0 ]]; then
    printf "$text" "$@"
  else
    printf '%s' "$text"
  fi
}

__deploy_i18n_message() {
  local key="$1"
  case "$key" in
    action.backup) echo "backup|backup" ;;
    action.install) echo "install|install" ;;
    action.status) echo "status|status" ;;
    action.uninstall) echo "uninstall|uninstall" ;;
    action.update) echo "update|update" ;;
    common.choose_action) echo "Choose an action:|请选择操作：" ;;
    common.invalid_choice) echo "Invalid choice: %s|无效选项：%s" ;;
    common.no_argument_menu) echo "No argument opens the interactive menu.|不带参数则打开交互式菜单。" ;;
    common.quit) echo "quit|退出" ;;
    common.selection_prompt) echo "Selection [1-5/q]:|请输入选项 [1-5/q]：" ;;
    common.usage) echo "Usage: sudo bash %s [install|update|backup|status|uninstall]|用法：sudo bash %s [install|update|backup|status|uninstall]" ;;
    config.loaded) echo "Loaded deployment config: %s|已加载部署记录：%s" ;;
    config.saved) echo "Saved deployment config: %s|部署配置已持久化：%s" ;;
    error.command_required) echo "Required command is missing: %s|缺少必要命令：%s" ;;
    error.config_permission) echo "Refusing to load unsafe config permissions: %s|拒绝加载权限不安全的配置文件：%s" ;;
    error.config_owner) echo "Refusing to load config not owned by root: %s|拒绝加载非 root 拥有的配置文件：%s" ;;
    error.config_write) echo "Failed to save deployment config: %s|部署配置保存失败：%s" ;;
    error.lock_failed) echo "Another deployment process is running: %s|已有部署进程正在运行：%s" ;;
    error.root_required) echo "Please run as root: sudo bash %s %s|请使用 root 权限运行：sudo bash %s %s" ;;
    error.unsupported_action) echo "%s does not support %s yet.|%s 暂不支持 %s。" ;;
    error.unsafe_path) echo "Unsafe path for %s: %s|%s 的路径不安全：%s" ;;
    menu.backup_desc) echo "create a manual backup|创建手动备份" ;;
    menu.install_desc) echo "full install or redeploy|完整安装或重新部署" ;;
    menu.status_desc) echo "show service and runtime status|查看服务和运行状态" ;;
    menu.uninstall_desc) echo "remove service and related files|卸载服务和相关文件" ;;
    menu.update_desc) echo "update to the latest available version|更新到可用的最新版本" ;;
    status.active) echo "active|运行中" ;;
    status.inactive) echo "inactive|未运行" ;;
    status.unknown) echo "unknown|未知" ;;
    warn.config_invalid_key) echo "Ignoring invalid config key: %s|已忽略非法配置键：%s" ;;
    warn.config_owner) echo "%s owner is not root (%s); ignoring it|%s 属主不是 root（当前：%s），已忽略" ;;
    warn.config_permission) echo "%s permissions are too open (%s); ignoring it|%s 权限过于宽松（%s），已忽略" ;;
    warn.config_unknown_key) echo "Ignoring unknown config key: %s|已忽略未知配置键：%s" ;;
    *) echo "$key|$key" ;;
  esac
}

t() {
  local key="$1"
  shift || true
  local pair text
  if [[ "$DEPLOY_LANG" == "zh" && -v "__DEPLOY_I18N_ZH[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_ZH[$key]}" "$@"
    return 0
  fi
  if [[ -v "__DEPLOY_I18N_EN[$key]" ]]; then
    i18n_print "${__DEPLOY_I18N_EN[$key]}" "$@"
    return 0
  fi
  pair="$(__deploy_i18n_message "$key")"
  if [[ "$DEPLOY_LANG" == "zh" ]]; then
    text="${pair#*|}"
  else
    text="${pair%%|*}"
  fi
  i18n_print "$text" "$@"
}

# ----- lib/logging.sh -----

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
BOLD='\033[1m'
NC='\033[0m'

info() { echo -e "${BLUE}[i]${NC} $*" >&2; }
success() { echo -e "${GREEN}[+]${NC} $*" >&2; }
warn() { echo -e "${YELLOW}[!]${NC} $*" >&2; }
error() { echo -e "${RED}[x]${NC} $*" >&2; exit 1; }
step() { echo -e "\n${CYAN}${BOLD}== $* ==${NC}" >&2; }
prompt() { echo -ne "${YELLOW}[?]${NC} $* " >&2; }

# ----- lib/fs.sh -----

require_root() {
  local action="${1:-}"
  [[ ${EUID:-$(id -u)} -eq 0 ]] || error "$(t error.root_required "$0" "$action")"
}

require_command() {
  local command_name="$1"
  command -v "$command_name" >/dev/null 2>&1 || error "$(t error.command_required "$command_name")"
}

is_safe_path() {
  local path="${1:-}"
  [[ -n "$path" ]] || return 1
  [[ "$path" = /* ]] || return 1

  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done

  case "$path" in
    /|.|..|*'/../'*|*'/..'|*'/./'*|*'/.')
      return 1
      ;;
    /bin|/boot|/dev|/etc|/home|/lib|/lib64|/opt|/proc|/root|/run|/sbin|/sys|/tmp|/usr|/var|/var/lib|/var/log|/usr/local|/usr/local/bin)
      return 1
      ;;
  esac
  return 0
}

require_safe_path() {
  local name="$1"
  local path="$2"
  is_safe_path "$path" || error "$(t error.unsafe_path "$name" "${path:-empty}")"
}

safe_rm_dir() {
  local path="$1"
  local name="${2:-path}"
  while [[ "$path" != "/" && "$path" == */ ]]; do
    path="${path%/}"
  done
  require_safe_path "$name" "$path"
  [[ -d "$path" ]] && rm -rf -- "$path"
}

# ----- lib/lock.sh -----

acquire_lock() {
  local lock_file="${1:-${LOCK_FILE:-}}"
  [[ -n "$lock_file" ]] || return 0
  mkdir -p "$(dirname "$lock_file")"
  exec 9>"$lock_file"
  flock -n 9 || error "$(t error.lock_failed "$lock_file")"
  trap 'release_lock' EXIT
}

release_lock() {
  flock -u 9 2>/dev/null || true
  exec 9>&- 2>/dev/null || true
}

# ----- lib/config.sh -----

sanitize_conf_val() {
  local newline=$'\n'
  local carriage_return=$'\r'
  local value="${1%%${newline}*}"
  value="${value%%${carriage_return}*}"
  value="${value//\"/}"
  echo "$value"
}

trim_conf_token() {
  local value="$1"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  printf '%s' "$value"
}

config_file_is_safe() {
  local conf_file="$1"
  [[ -f "$conf_file" ]] || return 0

  if command -v stat >/dev/null 2>&1; then
    local owner mode
    owner="$(stat -c '%U' "$conf_file" 2>/dev/null || echo unknown)"
    mode="$(stat -c '%a' "$conf_file" 2>/dev/null || echo 777)"
    [[ "$owner" == "root" ]] || error "$(t error.config_owner "$conf_file")"
    [[ "$mode" == "600" || "$mode" == "400" ]] || error "$(t error.config_permission "$conf_file")"
  fi
  return 0
}

load_config_file() {
  local conf_file="$1"
  shift
  local -a allowed_keys=("$@")
  [[ -f "$conf_file" ]] || return 0
  config_file_is_safe "$conf_file" || return 1

  local line key value allowed
  while IFS= read -r line || [[ -n "$line" ]]; do
    line="${line%$'\r'}"
    [[ "$line" =~ ^[[:space:]]*(#|$) || "$line" != *=* ]] && continue
    key="$(trim_conf_token "${line%%=*}")"
    if [[ ! "$key" =~ ^[A-Z_][A-Z0-9_]*$ ]]; then
      warn "$(t warn.config_invalid_key "$key")"
      continue
    fi
    value="$(trim_conf_token "${line#*=}")"
    if [[ "$value" =~ ^\"(.*)\"$ ]]; then
      value="${BASH_REMATCH[1]}"
    fi
    allowed=false
    local allowed_key
    for allowed_key in "${allowed_keys[@]}"; do
      if [[ "$key" == "$allowed_key" ]]; then
        allowed=true
        break
      fi
    done
    $allowed || { warn "$(t warn.config_unknown_key "$key")"; continue; }
    printf -v "$key" '%s' "$value"
  done < "$conf_file"
}

write_config_file() {
  local conf_file="$1"
  shift
  local tmp_file=""
  tmp_file="$(mktemp "${conf_file}.tmp.XXXXXX")" || return 1
  if ! chmod 600 "$tmp_file"; then
    rm -f "$tmp_file"
    return 1
  fi
  local key value
  for key in "$@"; do
    value="$(sanitize_conf_val "${!key:-}")"
    if ! printf '%s="%s"\n' "$key" "$value" >> "$tmp_file"; then
      rm -f "$tmp_file"
      return 1
    fi
  done
  if ! chown root:root "$tmp_file" 2>/dev/null; then
    rm -f "$tmp_file"
    return 1
  fi
  if ! mv "$tmp_file" "$conf_file"; then
    rm -f "$tmp_file"
    return 1
  fi
}

# ----- lib/service.sh -----

wait_for_service() {
  local service_name="$1"
  local timeout="${2:-20}"
  local elapsed=0
  while (( elapsed < timeout )); do
    if systemctl is-active --quiet "$service_name"; then
      return 0
    fi
    if systemctl is-failed --quiet "$service_name"; then
      return 1
    fi
    sleep 1
    elapsed=$((elapsed + 1))
  done
  return 1
}

service_status_label() {
  local service_name="$1"
  if systemctl is-active --quiet "$service_name" 2>/dev/null; then
    t status.active
  elif systemctl list-unit-files --no-legend --no-pager "$service_name.service" 2>/dev/null \
      | awk '{print $1}' \
      | grep -Fxq "$service_name.service"; then
    t status.inactive
  else
    t status.unknown
  fi
}

# ----- lib/network.sh -----

check_connectivity_urls() {
  local url
  for url in "$@"; do
    if curl -fsSL --max-time 8 -o /dev/null "$url" 2>/dev/null; then
      return 0
    fi
  done
  return 1
}

# ----- lib/app_loader.sh -----
BUNDLED_APP_IMPL_SCRIPT_NAME="install_cyberstrikeai_impl.sh"

ensure_bundled_impl_dir() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] && return 0

  local tmp_root
  tmp_root="${TMPDIR:-/tmp}"
  tmp_root="${tmp_root%/}"
  DEPLOY_BUNDLED_IMPL_DIR="$(mktemp -d "${tmp_root}/deploy-scripts.${APP_ID:-app}.XXXXXX")" \
    || error "Failed to create bundled implementation directory"
  if ! chmod 700 "$DEPLOY_BUNDLED_IMPL_DIR"; then
    safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
    unset DEPLOY_BUNDLED_IMPL_DIR
    error "Failed to secure bundled implementation directory"
  fi
}

app_impl_script_path() {
  local script="${APP_IMPL_SCRIPT:-}"
  if [[ "${DEPLOY_BUNDLED:-0}" == "1" ]]; then
    ensure_bundled_impl_dir
    echo "${DEPLOY_BUNDLED_IMPL_DIR}/${BUNDLED_APP_IMPL_SCRIPT_NAME}"
    return 0
  fi
  [[ -n "$script" ]] || error "APP_IMPL_SCRIPT is not configured for ${APP_ID:-unknown}"
  if [[ "$script" = /* ]]; then
    echo "$script"
  else
    echo "${DEPLOY_ROOT_DIR}/${script}"
  fi
}

ensure_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  local script_path tmp_path
  ensure_bundled_impl_dir
  script_path="$(app_impl_script_path)"
  tmp_path="$(mktemp "${script_path}.XXXXXX")" \
    || error "Failed to create bundled app implementation payload"
  if ! awk "/^__DEPLOY_APP_IMPL_SCRIPT__$/ { found=1; next } found { print }" "${BASH_SOURCE[0]}" > "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to extract bundled app implementation payload"
  fi
  if [[ ! -s "$tmp_path" ]]; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Bundled app implementation payload is empty"
  fi
  if ! chmod 700 "$tmp_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to secure bundled app implementation payload"
  fi
  if ! mv "$tmp_path" "$script_path"; then
    rm -f "$tmp_path"
    cleanup_bundled_app_impl_script
    error "Failed to install bundled app implementation payload"
  fi
}

cleanup_bundled_app_impl_script() {
  [[ "${DEPLOY_BUNDLED:-0}" == "1" ]] || return 0
  [[ -n "${DEPLOY_BUNDLED_IMPL_DIR:-}" ]] || return 0
  safe_rm_dir "$DEPLOY_BUNDLED_IMPL_DIR" "bundled implementation directory"
  unset DEPLOY_BUNDLED_IMPL_DIR
}

restore_framework_functions() {
  info() { echo -e "${BLUE}[i]${NC} $*" >&2; }
  success() { echo -e "${GREEN}[+]${NC} $*" >&2; }
  warn() { echo -e "${YELLOW}[!]${NC} $*" >&2; }
  error() { echo -e "${RED}[x]${NC} $*" >&2; exit 1; }
  step() { echo -e "\n${CYAN}${BOLD}== $* ==${NC}" >&2; }
  prompt() { echo -ne "${YELLOW}[?]${NC} $* " >&2; }

  show_banner() {
    echo -e "\n${BOLD}${CYAN}${APP_NAME:-Deployment Manager}${NC}"
    [[ -n "${APP_DESCRIPTION:-}" ]] && echo -e "${APP_DESCRIPTION}\n"
  }

  usage() {
    echo "$(t common.usage "$0")" >&2
    echo "      $(t common.no_argument_menu)" >&2
  }

  show_menu() {
    show_banner
    echo "$(t common.choose_action)"
    echo
    echo "  1) install    - $(t menu.install_desc)"
    echo "  2) update     - $(t menu.update_desc)"
    echo "  3) backup     - $(t menu.backup_desc)"
    echo "  4) status     - $(t menu.status_desc)"
    echo "  5) uninstall  - $(t menu.uninstall_desc)"
    echo "  q) $(t common.quit)"
    echo
    prompt "$(t common.selection_prompt)"
    local choice
    read -r choice
    dispatch_action "$choice"
  }

  dispatch_action() {
    local action="${1:-menu}"
    case "${action,,}" in
      install|1) do_install ;;
      update|2) do_update ;;
      backup|3) do_backup ;;
      status|4) do_status ;;
      uninstall|5) do_uninstall ;;
      menu|"") show_menu ;;
      q|quit|exit) exit 0 ;;
      *) error "$(t common.invalid_choice "$action")" ;;
    esac
  }
}

load_app_impl() {
  APP_IMPL_SCRIPT="$1"
  ensure_bundled_impl_dir
  ensure_bundled_app_impl_script
  local script_path
  script_path="$(app_impl_script_path)"
  [[ -f "$script_path" ]] || error "App implementation script not found: $script_path"
  if DEPLOY_IMPL_SOURCE_ONLY=1 source "$script_path"; then
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
  else
    local source_status=$?
    unset DEPLOY_IMPL_SOURCE_ONLY
    cleanup_bundled_app_impl_script
    return "$source_status"
  fi
  restore_framework_functions
}

# ----- lib/cli.sh -----

show_banner() {
  echo -e "\n${BOLD}${CYAN}${APP_NAME:-Deployment Manager}${NC}"
  [[ -n "${APP_DESCRIPTION:-}" ]] && echo -e "${APP_DESCRIPTION}\n"
}

usage() {
  echo "$(t common.usage "$0")" >&2
  echo "      $(t common.no_argument_menu)" >&2
}

show_menu() {
  show_banner
  echo "$(t common.choose_action)"
  echo
  echo "  1) install    - $(t menu.install_desc)"
  echo "  2) update     - $(t menu.update_desc)"
  echo "  3) backup     - $(t menu.backup_desc)"
  echo "  4) status     - $(t menu.status_desc)"
  echo "  5) uninstall  - $(t menu.uninstall_desc)"
  echo "  q) $(t common.quit)"
  echo
  prompt "$(t common.selection_prompt)"
  local choice
  read -r choice
  dispatch_action "$choice"
}

dispatch_action() {
  local action="${1:-menu}"
  case "${action,,}" in
    install|1) do_install ;;
    update|2) do_update ;;
    backup|3) do_backup ;;
    status|4) do_status ;;
    uninstall|5) do_uninstall ;;
    menu|"") show_menu ;;
    q|quit|exit) exit 0 ;;
    *) error "$(t common.invalid_choice "$action")" ;;
  esac
}

main() {
  dispatch_action "${1:-menu}"
}

